Write unit tests for this contract validation function:

```ts
export function validateContract(c: { startDate: Date; endDate: Date; value: number }): string[] {
  const errors: string[] = [];
  if (c.endDate <= c.startDate) errors.push("endDate must be after startDate");
  if (c.value <= 0) errors.push("value must be positive");
  return errors;
}
```
